`timescale 1ns/1ps
module tb_foundation_snmp_set_copy;
reg clk=0;always #40 clk=~clk;reg rst=1,request_valid=0;
reg [10:0] request_length=0;reg [4095:0] request_bytes=0;
reg [5:0] community_length=11;reg [255:0] community_bytes={168'd0,88'h747365742d746867696c66};
wire busy,done,valid,error;wire [10:0] response_length;wire [4095:0] response_bytes;wire [31:0] snapshots;
integer errors=0,cases=0,t,i,old_snapshots;
afdx_snmp_extended dut(.clk(clk),.rst(rst),.request_valid(request_valid),.request_length(request_length),.request_bytes(request_bytes),
.community_length(community_length),.community_bytes(community_bytes),.mib_values(800'd0),.busy(busy),.done(done),.response_valid(valid),.error(error),.error_code(),
.response_length(response_length),.response_bytes(response_bytes),.snapshot_event(),.snapshot_count(snapshots));
task fail;input [511:0] why;begin errors=errors+1;$display("FAIL SET_COPY case=%0d %0s",cases,why);end endtask
task query;input [4095:0] req,golden;input integer n,m,c;input [255:0] comm;begin
 old_snapshots=snapshots;@(negedge clk);request_bytes=req;request_length=n;community_length=c;community_bytes=comm;request_valid=1;
 @(negedge clk);request_valid=0;t=0;while(!done&&t<10000)begin @(negedge clk);t=t+1;end
 if(!done||!valid||error||response_length!=m||response_bytes!==golden||snapshots!=old_snapshots+1)fail("golden echo/length/snapshot/timeout");
 $write("SET_COPY_RESPONSE case=%0d hex=",cases);for(i=0;i<response_length;i=i+1)$write("%02x",response_bytes[i*8+:8]);$display("");
 cases=cases+1;repeat(3)@(negedge clk);
end endtask
initial begin repeat(4)@(negedge clk);rst=0;
query(4096',4096',376,376,11,256'h747365742d746867696c66);
query(4096'h63010201010159fd81010401062b0b06103012300001020001020101021da3747365742d746867696c660b040101022f30,4096'h63010201010159fd81010401062b0b06103012300101021101020101021da2747365742d746867696c660b040101022f30,49,49,11,256'h747365742d746867696c66);
query(4096',4096',432,432,32,256'h767574737271706f6e6d6c6b6a69686766656463626139383736353433323130);
query(4096',4096',512,512,11,256'h747365742d746867696c66);
query(4096'h63010201010159fd81010401062b0b06103012300001020001020101021da3747365742d746867696c660b040101022f30,4096'h63010201010159fd81010401062b0b06103012300101021101020101021da2747365742d746867696c660b040101022f30,49,49,11,256'h747365742d746867696c66);
@(negedge clk);request_bytes=4096';request_length=512;community_length=11;community_bytes=256'h747365742d746867696c66;request_valid=1;
@(negedge clk);request_valid=0;t=0;
while(dut.state!=11&&t<10000)begin @(negedge clk);t=t+1;end
if(dut.state!=11)fail("COPY_SET state never entered");repeat(8)@(negedge clk);rst=1;repeat(3)@(negedge clk);rst=0;
repeat(3)@(negedge clk);if(busy||done||valid||snapshots!=0)fail("reset abandoned copy");
query(4096'h63010201010159fd81010401062b0b06103012300001020001020101021da3747365742d746867696c660b040101022f30,4096'h63010201010159fd81010401062b0b06103012300101021101020101021da2747365742d746867696c660b040101022f30,49,49,11,256'h747365742d746867696c66);
$display("SET_COPY_CASES=%0d ERRORS=%0d",cases,errors);
if(errors==0)$display("TB_FOUNDATION_SNMP_SET_COPY_PASS");else $display("TB_FOUNDATION_SNMP_SET_COPY_FAIL");$finish;end
initial begin #10000000;$display("SET_COPY_TIMEOUT");$finish;end
endmodule
